solutionCode:
fun safeParseInt(text: String): Int {
    return try {
        text.toInt()
    } catch (e: NumberFormatException) {
        -1
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testValidNumber() {
        Assert.assertEquals(42, safeParseInt("42"))
    }

    @Test
    fun testInvalidText() {
        Assert.assertEquals(-1, safeParseInt("abc"))
    }

    @Test
    fun testEmptyString() {
        Assert.assertEquals(-1, safeParseInt(""))
    }

    @Test
    fun testNegativeNumber() {
        Assert.assertEquals(-5, safeParseInt("-5"))
    }

    @Test
    fun testZero() {
        Assert.assertEquals(0, safeParseInt("0"))
    }
}
